const out = [];
const seen = new Set();
for (const item of $input.all()) {
  const r = item.json || {};
  const activeRaw = (r['Active'] === undefined || r['Active'] === '') ? 'yes' : r['Active'];
  const active = String(activeRaw).trim().toLowerCase();
  if (['no', 'false', '0', 'paused', 'off'].includes(active)) continue;

  let url = String(r['URL'] || '').trim();
  if (!url) continue;
  if (!/^https?:\/\//i.test(url)) url = 'https://' + url;
  if (seen.has(url)) continue;
  seen.add(url);

  out.push({ json: {
    siteName: String(r['Site Name'] || url).trim(),
    url: url,
    expectedStatus: parseInt(r['Expected Status'], 10) || null,
    keyword: String(r['Expected Keyword'] || '').trim(),
    maxResponseMs: parseInt(r['Max Response ms'], 10) || 5000,
    failThreshold: Math.max(1, parseInt(r['Fail Threshold'], 10) || 2),
    alertEmail: String(r['Alert Email'] || '').trim()
  }});
}
return out;

const site = $('Stamp Start').item.json;
const r = $json || {};
const elapsed = Date.now() - site.startedAt;
const statusCode = (r.statusCode !== undefined && r.statusCode !== null) ? Number(r.statusCode) : null;
const body = typeof r.body === 'string' ? r.body : '';

let reason = null;
if (r.error || statusCode === null) {
  let msg = 'No response';
  if (typeof r.error === 'string') msg = r.error;
  else if (r.error && (r.error.message || r.error.description)) msg = r.error.message || r.error.description;
  reason = 'Request failed: ' + String(msg).slice(0, 200);
} else {
  const statusOk = site.expectedStatus ? statusCode === site.expectedStatus : (statusCode >= 200 && statusCode < 300);
  if (!statusOk) {
    reason = 'Unexpected HTTP status ' + statusCode + ' (expected ' + (site.expectedStatus || '2xx') + ')';
  } else if (site.keyword && !body.toLowerCase().includes(site.keyword.toLowerCase())) {
    reason = 'Expected keyword not found on page: "' + site.keyword + '"';
  }
}

const isUp = reason === null;
const isSlow = isUp && elapsed > site.maxResponseMs;
if (isSlow) reason = 'Slow response: ' + elapsed + ' ms (limit ' + site.maxResponseMs + ' ms)';

return { json: {
  siteName: site.siteName,
  url: site.url,
  keyword: site.keyword,
  maxResponseMs: site.maxResponseMs,
  failThreshold: site.failThreshold,
  alertEmail: site.alertEmail,
  statusCode: statusCode,
  responseMs: elapsed,
  isUp: isUp,
  isSlow: isSlow,
  reason: reason
} };

// Change this number to control how often a still-open incident is re-announced
const REMINDER_HOURS = 6;

const cur = $('Evaluate Result').item.json;
const prev = $json || {};
const nowMs = Date.now();
const nowIso = new Date(nowMs).toISOString();

const prevState = ['UP', 'DOWN', 'SLOW'].includes(prev['State']) ? prev['State'] : 'UP';
const prevCount = parseInt(prev['Problem Count'], 10) || 0;

const problem = !cur.isUp ? 'DOWN' : (cur.isSlow ? 'SLOW' : null);
const problemCount = problem ? prevCount + 1 : 0;

// State changes only after N bad checks in a row, but recovery is immediate
let newState = prevState;
if (!problem) newState = 'UP';
else if (problemCount >= cur.failThreshold) newState = problem;

let action = 'NONE';
const lastAlertMs = prev['Last Alert At'] ? Date.parse(prev['Last Alert At']) : 0;
if (newState !== prevState) {
  action = newState === 'UP' ? 'RECOVERED' : 'INCIDENT_OPEN';
} else if (newState !== 'UP' && lastAlertMs && (nowMs - lastAlertMs) >= REMINDER_HOURS * 3600000) {
  action = 'REMINDER';
}

let downSince = '';
if (problem) {
  downSince = (problemCount === 1 || !prev['Down Since']) ? nowIso : prev['Down Since'];
}

const startIso = problem ? downSince : (prev['Down Since'] || '');
let durationMin = null;
if (startIso && !isNaN(Date.parse(startIso))) {
  durationMin = Math.max(0, Math.round((nowMs - Date.parse(startIso)) / 60000));
}

return { json: {
  ...cur,
  prevState: prevState,
  newState: newState,
  action: action,
  problemCount: problemCount,
  downSince: downSince,
  previousDownSince: prev['Down Since'] || '',
  prevReason: prev['Last Reason'] || '',
  durationMin: durationMin,
  lastAlertAt: action !== 'NONE' ? nowIso : (prev['Last Alert At'] || ''),
  checkedAt: nowIso
} };

const d = $json;
const fmt = (min) => {
  if (min === null || min === undefined || isNaN(min)) return 'unknown time';
  const h = Math.floor(min / 60);
  const m = min % 60;
  return h > 0 ? h + 'h ' + m + 'm' : m + 'm';
};

let icon, title, detail, tag;
if (d.action === 'RECOVERED') {
  icon = ':large_green_circle:';
  tag = 'RECOVERED';
  title = 'RECOVERED: ' + d.siteName;
  detail = 'Back to normal after ' + fmt(d.durationMin) + ' (' + d.prevState.toLowerCase() + ' incident). Response time: ' + d.responseMs + ' ms.';
} else if (d.action === 'REMINDER') {
  icon = ':rotating_light:';
  tag = d.newState;
  title = 'STILL ' + d.newState + ': ' + d.siteName;
  detail = d.reason + '. Ongoing for ' + fmt(d.durationMin) + '.';
} else {
  icon = d.newState === 'DOWN' ? ':red_circle:' : ':large_yellow_circle:';
  tag = d.newState;
  title = (d.newState === 'DOWN' ? 'SITE DOWN: ' : 'SITE SLOW: ') + d.siteName;
  detail = d.reason;
}

const lines = [
  icon + ' *' + title + '*',
  '*URL:* ' + d.url,
  '*Details:* ' + detail,
  '*HTTP status:* ' + (d.statusCode === null ? 'no response' : d.statusCode),
  '*Response time:* ' + d.responseMs + ' ms',
  '*Checked at:* ' + d.checkedAt
];

const plain = [
  title,
  '',
  'URL: ' + d.url,
  'Details: ' + detail,
  'HTTP status: ' + (d.statusCode === null ? 'no response' : d.statusCode),
  'Response time: ' + d.responseMs + ' ms',
  'Checked at: ' + d.checkedAt
];

return { json: {
  slackText: lines.join('\n'),
  emailSubject: '[' + tag + '] ' + d.siteName,
  emailBody: plain.join('\n')
} };

const states = $('Read Site State').all().map(i => i.json).filter(r => r['Site URL']);
const history = $('Read Incident History').all().map(i => i.json).filter(r => r['Site URL']);

const cutoff = Date.now() - 24 * 3600000;
const closed = history.filter(h => {
  const t = Date.parse(h['Recovered At']);
  return !isNaN(t) && t >= cutoff;
});
const downtime = closed.reduce((s, h) => s + (parseInt(h['Duration Minutes'], 10) || 0), 0);

const down = states.filter(s => s['State'] === 'DOWN');
const slow = states.filter(s => s['State'] === 'SLOW');
const up = states.filter(s => s['State'] === 'UP');

const slowest = states
  .filter(s => parseInt(s['Last Response ms'], 10) > 0)
  .sort((a, b) => parseInt(b['Last Response ms'], 10) - parseInt(a['Last Response ms'], 10))
  .slice(0, 3);

const lines = [];
lines.push(':bar_chart: *Daily uptime digest* (' + new Date().toISOString().slice(0, 10) + ')');
lines.push('*Monitored:* ' + states.length + '  |  *Up:* ' + up.length + '  |  *Slow:* ' + slow.length + '  |  *Down:* ' + down.length);

if (down.length) {
  lines.push('');
  lines.push(':red_circle: *Down right now*');
  down.forEach(s => lines.push('- ' + s['Site Name'] + ' since ' + (s['Down Since'] || 'unknown')));
}
if (slow.length) {
  lines.push('');
  lines.push(':large_yellow_circle: *Slow right now*');
  slow.forEach(s => lines.push('- ' + s['Site Name'] + ' (' + s['Last Response ms'] + ' ms)'));
}

lines.push('');
lines.push('*Incidents closed in last 24h:* ' + closed.length + '  |  *Total downtime:* ' + downtime + ' min');

if (slowest.length) {
  lines.push('');
  lines.push('*Slowest sites at last check*');
  slowest.forEach(s => lines.push('- ' + s['Site Name'] + ': ' + s['Last Response ms'] + ' ms'));
}

if (!states.length) {
  lines.push('');
  lines.push('No site state yet. Check that the Sites tab has active rows and the main workflow is running.');
}

return [{ json: { text: lines.join('\n') } }];

const e = $json || {};
const wf = (e.workflow && e.workflow.name) || 'Website Uptime Watchdog';
const ex = e.execution || {};
const msg = (ex.error && ex.error.message) || 'No error message available';
const text = [
  ':warning: *Uptime Watchdog crashed*',
  '*Workflow:* ' + wf,
  '*Failed node:* ' + (ex.lastNodeExecuted || 'unknown'),
  '*Error:* ' + msg,
  '*Execution:* ' + (ex.url || 'n/a'),
  '',
  'Monitoring is paused until this is fixed.'
].join('\n');
return [{ json: { text: text } }];
